// Carpeta montada desde el host en el docker run (ver n8n/README.md)
const RUTA_BASE = "/home/node/datos";

// Lista blanca para nombres de carpeta: letras (con tildes), números, espacio, punto, guion y guion bajo.
// Estos valores terminan en un comando de shell, así que todo lo demás se descarta
// (incluye $ ` ; & | " \ y saltos de línea).
function limpiar(texto) {
  return String(texto)
    .normalize("NFC")
    .replace(/[^\p{L}\p{N} ._-]/gu, "")
    .replace(/\s+/g, " ")
    .replace(/^[.\s]+|[.\s]+$/g, "")
    .slice(0, 80);
}

return $input.all().map(item => {
  const data = item.json;

  const fechaTexto = String(data.FECHA_ISO || "");
  const fecha = /^\d{4}-\d{2}-\d{2}$/.test(fechaTexto) ? fechaTexto : "SIN_FECHA";

  const obligacionNumero = String(data.OBLIGACION_PROPUESTA || "").replace(/\D/g, "");
  const obligacion = obligacionNumero || "SIN_OBLIGACION";

  const tituloBase = data.TITULO_ACTIVIDAD || data.ACTIVIDAD_CORREGIDA || data.ACTIVIDAD_BASE || "SIN_TITULO";
  const tituloLimpio = limpiar(tituloBase) || "SIN_TITULO";

  const rutaCarpeta = `${RUTA_BASE}/OBLIGACION_${obligacion}/${fecha}_${tituloLimpio}`;
  const rutaArchivo = `${rutaCarpeta}/LEEME.txt`;

  return {
    json: {
      ...data,
      ruta_carpeta_docker: rutaCarpeta,
      ruta_archivo_docker: rutaArchivo,
      texto_evidencia: `Control de actividad: ${tituloLimpio} del día ${fecha}`
    }
  };
});
